#include "engine_effects.hpp"
#include "meter_artwork.hpp"
#include <iostream>
using namespace ofo;
int main(int argc,char**argv){try{if(argc<2)throw std::runtime_error("Pass original data directory");Resources r(argv[1]);auto p=load_effect_parameters(r);Json report={{"source","particle/effectparams.txt"},{"native_fire_start",p.fire_start},{"native_fire_offset",{p.fire_offset.x,p.fire_offset.y,p.fire_offset.z}},{"native_fire_life",p.fire_life},{"native_fire_velocity",p.fire_velocity},{"native_fire_size_per_radius",p.fire_size},{"native_fire_grow",p.fire_grow},{"native_fire_alpha",p.fire_alpha},{"native_fire_iterations",p.fire_iterations},{"menu_script","scripts/internal.bed SetMenuCamera(camnum==20) -> StartSmoke(Dummies.title_smoke.Position)"},{"menu_position",bed_file(r,"tracks/menu/menu1/a/data/dummies.bed").at("Dummies").at("title_smoke").at("Position")},{"smoke_thresholds_adapter",{.25,.5}},{"damage_model","basic impact prototype; J/m * .025, 1170Ns minimum, closing>=2m/s, .12s cooldown"},{"atlas","tracks/<family>/textures/particles.dds; 512x512"},{"atlas_rectangles",{{"white_smoke",{256,256,128,128}},{"black_smoke",{128,384,128,128}},{"fire",{384,256,128,128}}}},{"previews",Json::array()}};
 for(bool battle:{false,true})for(float charge:{0.f,.5f,1.f}){Json preview={{"mode",battle?"damage":"nitro"},{"value",charge},{"layers",Json::array()}};for(auto&layer:meter_artwork(battle,false,charge,charge))preview["layers"].push_back({{"texture",layer.texture},{"rect",{layer.x,layer.y,layer.w,layer.h}}});report["previews"].push_back(preview);}std::cout<<report.dump(2)<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
